/* ============ skins.js — how each alternate form (skin) is unlocked ============
 * The forms themselves (sprite ids, labels, categories) are in js/data/forms.js (G.FORMS, generated by
 * tools/fetch_forms.py). This file gives each one a route (28-10-2026, see the "Megamon Form Skins & Mastery
 * Design" doc):
 *   mega       Megas and Primals: Mastery 10 AND reach Arceus with that Pokémon (its gold star)
 *   mastery    female variants at Mastery 5; signature forms at the level in SIG
 *   challenge  a themed feat (CHAL below; the counters live in save.fc, see systems/skins.js)
 *   shop       bought with PokéCoins at Smeargle's Studio (price by shelf)
 * Skins are cosmetic only: stats, types, moves, ability and hitbox stay the base Pokémon's.
 */
G.SkinData = (() => {
  const TYPES = ['normal', 'fire', 'water', 'grass', 'electric', 'ice', 'fighting', 'poison', 'ground', 'flying',
                 'psychic', 'bug', 'rock', 'ghost', 'dragon', 'dark', 'steel', 'fairy'];
  const cap = t => t.charAt(0).toUpperCase() + t.slice(1);

  // Signature forms from Mastery: dex -> { form label: Mastery level }.
  const SIG = {
    555: { Zen: 3 }, 649: { Douse: 2, Shock: 4, Burn: 6, Chill: 8 }, 670: { Eternal: 8 }, 681: { Blade: 3 },
    716: { Neutral: 3 }, 718: { '10%': 3, Complete: 8 }, 720: { Unbound: 7 }, 746: { School: 3 }, 800: { Ultra: 8 },
    870: { Trooper: 3 }, 875: { Noice: 3 }, 888: { 'Crowned Sword': 8 }, 889: { 'Crowned Shield': 8 },
    892: { 'Rapid Strike': 5 }, 901: { Bloodmoon: 8 }, 964: { Hero: 5 }, 492: { Sky: 5 }, 648: { Pirouette: 5 },
    1017: { Wellspring: 3, Hearthflame: 5, Cornerstone: 7 }, 1024: { Terastal: 8 }
  };

  // Shop prices (PokéCoins).
  const PRICE = { legendRegional: 5000, regional: 2000, rotom: 1500, distinct: 800, colour: 600, bigSet: 300 };
  const COLOUR = new Set([412, 413, 422, 423, 550, 669, 671]);           // + Floette's colours (670, not Eternal/Mega)
  const BIGSET = new Set([666, 869]);                                   // Vivillon, Alcremie
  const LEGEND_REGIONAL = new Set([144, 145, 146]);                     // Galarian birds

  // Challenge forms. `val(s)` = progress in the save, `goal` = needed; `ev` = granted by an event (systems/skins.js).
  // `text` is shown on the reward track and the skin picker.
  const fc = s => s.fc || {};
  const arenas = s => s.arenas || {};
  function challenge(dex, form) {
    switch (dex) {
      case 493: {                                                       // Arceus
        if (form === '???') return { text: 'Win all 18 rift arenas', goal: 18, val: s => Object.keys(arenas(s)).length };
        const t = form.toLowerCase();
        return { text: 'Win the ' + form + ' rift arena with any Pokémon', goal: 1, val: s => (arenas(s)[t] ? 1 : 0) };
      }
      case 773: {                                                       // Silvally
        const t = form.toLowerCase();
        return { text: 'As Silvally, defeat 300 ' + form + '-type Pokémon (any number of runs)', goal: 300,
                 val: s => ((fc(s).sv || {})[t] || 0) };
      }
      case 201: return { text: 'Clear Unown Sequence floors in the Battle Tower: each one reveals a letter you don\'t have', ev: 1 };
      case 351: {                                                       // Castform
        const k = { Sunny: 'sun', Rainy: 'rain', Snowy: 'snow' }[form];
        const w = { sun: 'harsh sun', rain: 'rain', snow: 'snow' }[k];
        return { text: 'As Castform, spend 3 minutes in ' + w + ' (any number of runs)', goal: 180, unit: 's',
                 val: s => Math.floor(((fc(s).wx || {})[k]) || 0) };
      }
      case 421: return { text: 'As Cherrim, spend 5 minutes in harsh sun (any number of runs)', goal: 300, unit: 's',
                         val: s => Math.floor(fc(s).cs || 0) };
      case 585: case 586: {
        const months = { Summer: 'June, July or August', Autumn: 'September, October or November', Winter: 'December, January or February' }[form];
        return { text: 'Play a run as ' + G.DEX_BY[dex].name + ' in ' + months, ev: 1 };
      }
      case 386: {
        const perk = { Attack: 'Power', Defense: 'Armor', Speed: 'Reflexes' }[form];
        return { text: 'As Deoxys, max out the ' + perk + ' perk in one run', ev: 1 };
      }
      case 483: case 484: case 487:
        return { text: 'Defeat ' + G.DEX_BY[dex].name + ' in a rift with Roar at level 5 or higher', ev: 1 };
      case 645: case 905:
        return { text: 'Defeat ' + G.DEX_BY[dex].name + ' in a rift 3 times', goal: 3, val: s => ((fc(s).th || {})[dex] || 0) };
      case 646:
        return { text: 'As Kyurem, defeat ' + (form === 'Black' ? 'Zekrom' : 'Reshiram') + ' in a rift', ev: 1 };
      case 778: return { text: 'As Mimikyu, let Disguise block 25 hits (any number of runs)', goal: 25, val: s => (fc(s).dg || 0) };
      case 25:
        if (form === 'Libre') return { text: 'As Pikachu, defeat 500 Pokémon in one run with only physical moves', ev: 1 };
        if (form === 'Cosplay') return { text: 'Own 10 other skins', goal: 10, val: s => G.Skins.count(s, true) };
    }
    return null;
  }
  const CHAL_DEX = new Set([493, 773, 201, 351, 421, 585, 586, 386, 483, 484, 487, 645, 905, 646, 778, 25]);

  /** Display name of a form: "Mega Charizard X", "Alolan Raichu", "Raichu ♀", "Castform (Sunny)". */
  function nameOf(f) {
    const mon = G.DEX_BY[f.dex], n = mon ? mon.name : '#' + f.dex, l = f.form;
    if (f.cat === 'mega') {
      if (l === 'Primal') return 'Primal ' + n;
      const m = /^Mega(?: (\w))?$/.exec(l);
      return m ? 'Mega ' + n + (m[1] ? ' ' + m[1] : '') : n + ' (' + l + ')';
    }
    if (f.cat === 'female') return n + ' ♀';
    if (f.cat === 'regional') {
      if (f.dex === 128) return 'Paldean Tauros (' + ({ Paldea: 'Combat', 'Paldea Blaze': 'Blaze', 'Paldea Aqua': 'Aqua' }[l] || l) + ' Breed)';
      const adj = { Alola: 'Alolan', Galar: 'Galarian', Hisui: 'Hisuian', Paldea: 'Paldean' }[l.split(' ')[0]];
      return (adj || l) + ' ' + n;
    }
    if (f.dex === 201) return 'Unown ' + l;
    if ((f.dex === 493 || f.dex === 773) && l !== '???') return n + ' (' + l + ' type)';
    return n + ' (' + l + ')';
  }

  /** The route of a form: { kind, level?, price?, shelf?, ch? }. */
  function routeOf(f) {
    if (f.cat === 'mega') return { kind: 'mega' };
    if (f.cat === 'female') return { kind: 'mastery', level: 5 };
    const sig = SIG[f.dex] && SIG[f.dex][f.form];
    if (sig) return { kind: 'mastery', level: sig };
    if (CHAL_DEX.has(f.dex)) { const ch = challenge(f.dex, f.form); if (ch) return { kind: 'challenge', ch }; }
    if (f.cat === 'regional') {
      return { kind: 'shop', shelf: 'regional', price: LEGEND_REGIONAL.has(f.dex) ? PRICE.legendRegional : PRICE.regional };
    }
    if (f.dex === 479) return { kind: 'shop', shelf: 'colours', price: PRICE.rotom };
    if (BIGSET.has(f.dex)) return { kind: 'shop', shelf: 'colours', price: PRICE.bigSet };
    if (COLOUR.has(f.dex) || f.dex === 670) return { kind: 'shop', shelf: 'colours', price: PRICE.colour };
    return { kind: 'shop', shelf: 'colours', price: PRICE.distinct };
  }

  // ---- the catalogue ----
  const LIST = [], BY = {}, OF = {};
  for (const [id, dex, form, cat, full] of (G.FORMS || [])) {
    if (!G.DEX_BY[dex] || !G.SPRITE_META[id]) continue;                 // species not in the game (Gimmighoul, Falinks)
    const f = { id, dex, form, cat, full: !!full };
    f.name = nameOf(f);
    f.route = routeOf(f);
    LIST.push(f); BY[id] = f;
    (OF[dex] = OF[dex] || []).push(f);
  }

  // Sets that give an achievement when complete (data/achievements.js, Forms category).
  const SETS = [
    { id: 'setArceus', name: 'Multitype', dex: 493, title: 'Plate Keeper' },
    { id: 'setSilvally', name: 'RKS System', dex: 773, title: 'Memory Keeper' },
    { id: 'setUnown', name: 'Unown Report', dex: 201, title: 'Unown Scholar' },
    { id: 'setVivillon', name: 'World Traveller', dex: 666, title: 'Globetrotter' },
    { id: 'setAlcremie', name: 'Sweet Tooth', dex: 869, title: 'Patissier' },
    { id: 'setMinior', name: 'Rainbow Core', dex: 774, title: 'Stargazer' },
    { id: 'setRotom', name: 'Appliance Expert', dex: 479, title: 'Handyman' }
  ];

  return { LIST, BY, OF, SIG, PRICE, SETS, TYPES, nameOf, cap };
})();
